      chatsBg: onChats ? '#0B6E4F' : '#E9EEEB',
      chatsInk: onChats ? '#FFFFFF' : '#0E1F19',
      alertsBg: onChats ? '#E9EEEB' : '#0B6E4F',
      alertsInk: onChats ? '#0E1F19' : '#FFFFFF',
      showChats: () => this.setState({ tab: 'chats' }),
      showAlerts: () => this.setState({ tab: 'alerts' }),
      alerts: ALERTS_USE.map((a) => ({ ...a, bg: a.fresh ? '#FCEBD6' : '#FFFFFF' })),
      sellerLine: 'A buyer said ₦' + price,
